// Originals are stored once; subsequent transactions update only metadata.
export function createSessionStore({indexedDB=globalThis.indexedDB,name='film-lab-sessions',onStatus=()=>{}}={}){
 let dbPromise=null,scope='guest',revision=0,initialized=false,latest=null,sequence=0,savedSequence=0,running=null,failure=null,fingerprint=null;
 const writer=crypto.randomUUID();
 function open(){if(!indexedDB)return Promise.reject(new Error('LOCAL_UNAVAILABLE'));if(dbPromise)return dbPromise;dbPromise=new Promise((resolve,reject)=>{const req=indexedDB.open(name,1);req.onupgradeneeded=()=>{const db=req.result;db.createObjectStore('sessions',{keyPath:'scope'});db.createObjectStore('originals',{keyPath:'key'});};req.onerror=()=>reject(req.error);req.onblocked=()=>reject(new Error('LOCAL_BLOCKED'));req.onsuccess=()=>{req.result.onversionchange=()=>req.result.close();resolve(req.result);};});return dbPromise;}
 const done=tx=>new Promise((resolve,reject)=>{tx.oncomplete=resolve;tx.onabort=()=>reject(tx.error||new Error('LOCAL_TRANSACTION_ABORTED'));tx.onerror=()=>{};});
 async function read(target){const db=await open(),tx=db.transaction(['sessions','originals'],'readonly'),finished=done(tx);let snapshot=null;const files=new Map();tx.objectStore('sessions').get(target).onsuccess=e=>{snapshot=e.target.result||null;if(snapshot)for(const photo of snapshot.photos||[]){tx.objectStore('originals').get(target+':'+photo.id).onsuccess=e=>{if(e.target.result)files.set(photo.id,e.target.result);};}};await finished;if(snapshot){for(const photo of snapshot.photos||[]){const original=files.get(photo.id);if(!original)throw new Error('LOCAL_ORIGINAL_MISSING');photo.file=new File([original.blob],original.name,{type:original.type,lastModified:original.lastModified});}}return snapshot;}
 async function switchScope(uid){if(initialized)await flush();scope=uid?'user:'+uid:'guest';latest=null;sequence=0;savedSequence=0;failure=null;fingerprint=null;let record=null;try{record=await read(scope);revision=record?.revision||0;initialized=true;onStatus(record?.photos?.length?'Sesión anterior disponible en este dispositivo':'Guardado automático en este dispositivo',false);return record;}catch(error){revision=0;initialized=true;failure=error;onStatus(localMessage(error),true);return null;}}
 function localMessage(error){if(error?.name==='QuotaExceededError')return 'Sin espacio en este dispositivo. No cierres la pestaña: exportá o esperá la copia en la nube.';if(error?.message==='LOCAL_CONFLICT')return 'Otra pestaña modificó esta sesión. Esta pestaña no sobrescribirá su copia local; guardá o exportá tus cambios.';if(error?.message==='LOCAL_ORIGINAL_MISSING')return 'Falta un original de la copia local. Abrí el proyecto desde tu cuenta si está sincronizado.';return 'No pudimos guardar la sesión en este dispositivo. No cierres la pestaña hasta guardar o exportar tus archivos.';}
 function save(snapshot,photos){if(!initialized)return Promise.resolve(false);const nextFingerprint=JSON.stringify(snapshot);if(nextFingerprint===fingerprint&&!failure)return running||Promise.resolve(true);fingerprint=nextFingerprint;latest={scope,revision,snapshot:structuredClone(snapshot),photos:photos.filter(p=>!p.isDemo).map(p=>({id:p.id,file:p.file})),sequence:++sequence};failure=null;onStatus('Guardando en este dispositivo…',false);return drain();}
 async function commit(job){const db=await open(),tx=db.transaction(['sessions','originals'],'readwrite'),finished=done(tx);let conflict=false,nextRevision=0;const sessions=tx.objectStore('sessions'),originals=tx.objectStore('originals');sessions.get(job.scope).onsuccess=e=>{const previous=e.target.result;if((previous?.revision||0)!==revision&&previous?.writer!==writer){conflict=true;tx.abort();return;}nextRevision=(previous?.revision||0)+1;const ids=new Set(job.photos.map(p=>p.id));for(const p of previous?.photos||[])if(!ids.has(p.id))originals.delete(job.scope+':'+p.id);for(const p of job.photos){const key=job.scope+':'+p.id;originals.get(key).onsuccess=e=>{if(!e.target.result)originals.put({key,blob:p.file,name:p.file.name,type:p.file.type,lastModified:p.file.lastModified});};}sessions.put({...job.snapshot,scope:job.scope,revision:nextRevision,writer,savedAt:Date.now()});};try{await finished;}catch(error){if(conflict)throw new Error('LOCAL_CONFLICT');throw error;}return nextRevision;}
 function drain(){if(running)return running;running=(async()=>{while(latest&&savedSequence<latest.sequence){const job=latest;try{revision=await commit(job);savedSequence=job.sequence;failure=null;if(savedSequence===sequence)onStatus('Guardado en este dispositivo · '+new Date().toLocaleTimeString('es-AR',{hour:'2-digit',minute:'2-digit'}),false);}catch(error){failure=error;onStatus(localMessage(error),true);return false;}}return !failure;})().finally(()=>{running=null;});return running;}
 async function flush(){if(running)await running;if(latest&&savedSequence<latest.sequence&&!failure)await drain();return !failure&&savedSequence===sequence;}
 async function close(){await flush();if(dbPromise){try{(await dbPromise).close();}catch{}}}
 return {switchScope,save,flush,close,scope:()=>scope,hasUnsaved:()=>!!failure||savedSequence!==sequence,ready:()=>initialized,read};
}
